CREATE TABLE IF NOT EXISTS sys_user (id BIGINT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(50) NOT NULL UNIQUE, password VARCHAR(200) NOT NULL, nickname VARCHAR(50), avatar VARCHAR(255), phone VARCHAR(20), role VARCHAR(10) NOT NULL, status VARCHAR(10) DEFAULT 'ENABLED', last_login_time TIMESTAMP, create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, deleted INT DEFAULT 0);
CREATE TABLE IF NOT EXISTS elderly_profile (id BIGINT AUTO_INCREMENT PRIMARY KEY, family_id BIGINT NOT NULL, name VARCHAR(30) NOT NULL, gender VARCHAR(10) NOT NULL, birth_date DATE NOT NULL, id_card VARCHAR(200) NOT NULL, phone VARCHAR(20), address VARCHAR(200), emergency_contact VARCHAR(20), emergency_name VARCHAR(30), mobility VARCHAR(10), allergy_history TEXT, chronic_disease TEXT, remark VARCHAR(500), create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, deleted INT DEFAULT 0);
CREATE TABLE IF NOT EXISTS escort_profile (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL UNIQUE, real_name VARCHAR(30) NOT NULL, gender VARCHAR(10) NOT NULL, birth_date DATE NOT NULL, id_card VARCHAR(200) NOT NULL, phone VARCHAR(20) NOT NULL, service_city VARCHAR(50) NOT NULL, service_area VARCHAR(200), intro VARCHAR(500), materials TEXT, audit_status VARCHAR(10) DEFAULT 'PENDING', audit_remark VARCHAR(500), audit_time TIMESTAMP, auditor_id BIGINT, avg_rating DECIMAL(3,2) DEFAULT 5.00, total_orders INT DEFAULT 0, create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, deleted INT DEFAULT 0);
CREATE TABLE IF NOT EXISTS hospital (id BIGINT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, address VARCHAR(200) NOT NULL, city VARCHAR(50) NOT NULL, level VARCHAR(10) NOT NULL, phone VARCHAR(20), departments TEXT NOT NULL, description VARCHAR(500), create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, deleted INT DEFAULT 0);
CREATE TABLE IF NOT EXISTS escort_order (id BIGINT AUTO_INCREMENT PRIMARY KEY, order_no VARCHAR(20) NOT NULL UNIQUE, family_id BIGINT NOT NULL, elderly_id BIGINT NOT NULL, escort_id BIGINT, hospital_id BIGINT NOT NULL, department VARCHAR(50) NOT NULL, service_type VARCHAR(10) NOT NULL, appointment_time TIMESTAMP NOT NULL, duration DECIMAL(4,1) DEFAULT 1.0, amount DECIMAL(10,2) NOT NULL, status VARCHAR(20) DEFAULT 'PENDING_DISPATCH', version INT DEFAULT 0, pay_status VARCHAR(20) DEFAULT 'UNPAID', pay_time TIMESTAMP, cancel_reason VARCHAR(500), refund_amount DECIMAL(10,2), remark VARCHAR(500), request_id VARCHAR(64) UNIQUE, create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, deleted INT DEFAULT 0);
CREATE TABLE IF NOT EXISTS order_status_log (id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id BIGINT NOT NULL, order_no VARCHAR(20) NOT NULL, from_status VARCHAR(20), to_status VARCHAR(20) NOT NULL, operator_id BIGINT NOT NULL, operator_role VARCHAR(10) NOT NULL, remark VARCHAR(500), create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, deleted INT DEFAULT 0);
CREATE TABLE IF NOT EXISTS settlement (id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id BIGINT NOT NULL UNIQUE, order_no VARCHAR(20) NOT NULL, escort_id BIGINT NOT NULL, order_amount DECIMAL(10,2) NOT NULL, platform_rate DECIMAL(4,2) NOT NULL, platform_fee DECIMAL(10,2) NOT NULL, escort_income DECIMAL(10,2) NOT NULL, settle_status VARCHAR(20) DEFAULT 'SETTLED', operator_id BIGINT NOT NULL, remark VARCHAR(500), create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, deleted INT DEFAULT 0);
CREATE TABLE IF NOT EXISTS evaluation (id BIGINT AUTO_INCREMENT PRIMARY KEY, order_id BIGINT NOT NULL UNIQUE, order_no VARCHAR(20) NOT NULL, family_id BIGINT NOT NULL, escort_id BIGINT NOT NULL, score INT NOT NULL, content VARCHAR(1000), is_hidden INT DEFAULT 0, hide_reason VARCHAR(500), create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, deleted INT DEFAULT 0);
CREATE TABLE IF NOT EXISTS medical_record (id BIGINT AUTO_INCREMENT PRIMARY KEY, elderly_id BIGINT NOT NULL, order_id BIGINT, hospital_id BIGINT NOT NULL, department VARCHAR(50) NOT NULL, visit_date DATE NOT NULL, chief_complaint VARCHAR(500), diagnosis VARCHAR(500), prescription TEXT, remark VARCHAR(500), create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, deleted INT DEFAULT 0);
CREATE TABLE IF NOT EXISTS medical_document (id BIGINT AUTO_INCREMENT PRIMARY KEY, record_id BIGINT NOT NULL, doc_type VARCHAR(20) NOT NULL, image_url VARCHAR(255) NOT NULL, ocr_status VARCHAR(20) DEFAULT 'PENDING', ocr_result TEXT, ocr_confidence DECIMAL(4,2), manual_confirmed INT DEFAULT 0, confirmed_by BIGINT, confirmed_time TIMESTAMP, create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, deleted INT DEFAULT 0);
CREATE TABLE IF NOT EXISTS ai_task (id BIGINT AUTO_INCREMENT PRIMARY KEY, task_type VARCHAR(10) NOT NULL, biz_id BIGINT NOT NULL, status VARCHAR(10) DEFAULT 'RUNNING', retry_count INT DEFAULT 0, error_msg VARCHAR(1000), start_time TIMESTAMP NOT NULL, end_time TIMESTAMP, cost_ms INT, request_digest VARCHAR(500), response_digest VARCHAR(500), create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, deleted INT DEFAULT 0);
CREATE TABLE IF NOT EXISTS ai_generated_content (id BIGINT AUTO_INCREMENT PRIMARY KEY, task_id BIGINT NOT NULL UNIQUE, content_type VARCHAR(10) NOT NULL, biz_id BIGINT NOT NULL, content TEXT NOT NULL, disclaimer VARCHAR(200) NOT NULL, review_status VARCHAR(20) DEFAULT 'UNREVIEWED', reviewer_id BIGINT, review_time TIMESTAMP, review_remark VARCHAR(500), create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, deleted INT DEFAULT 0);
CREATE TABLE IF NOT EXISTS sys_notification (id BIGINT AUTO_INCREMENT PRIMARY KEY, recipient_id BIGINT NOT NULL, title VARCHAR(100) NOT NULL, content VARCHAR(500) NOT NULL, biz_type VARCHAR(20), biz_id BIGINT, is_read INT DEFAULT 0, read_time TIMESTAMP, create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, deleted INT DEFAULT 0);

CREATE TABLE IF NOT EXISTS ai_chat_session (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, title VARCHAR(100), context_type VARCHAR(20), context_id BIGINT, system_prompt TEXT, create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, update_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP, deleted INT DEFAULT 0);
CREATE TABLE IF NOT EXISTS ai_chat_message (id BIGINT AUTO_INCREMENT PRIMARY KEY, session_id BIGINT NOT NULL, role VARCHAR(10) NOT NULL, content TEXT NOT NULL, token_count INT, create_time TIMESTAMP DEFAULT CURRENT_TIMESTAMP);

